INSERT INTO FactHoldings (SK_CustomerID, SK_AccountID, SK_SecurityID, SK_CompanyID, CurrentPrice, SK_DateID, SK_TimeID, TradeID, CurrentTradeID, CurrentHolding, BatchID) SELECT CAST(DT.SK_CustomerID AS INT) AS SK_CustomerID, CAST(DT.SK_AccountID AS INT) AS SK_AccountID, CAST(DT.SK_SecurityID AS INT) AS SK_SecurityID, CAST(DT.SK_CompanyID AS INT) AS SK_CompanyID, CAST(COALESCE(TRY_CAST(DT.TradePrice AS DECIMAL(8, 2)), 1) AS INT) AS CurrentPrice, CAST(COALESCE(DT.SK_CloseDateID, DT.SK_CreateDateID) AS INT) AS SK_DateID, CAST(COALESCE(DT.SK_CloseTimeID, DT.SK_CreateTimeID) AS INT) AS SK_TimeID, CAST(HH.HH_H_T_ID AS INT) AS TradeID, CAST(HH.HH_T_ID AS INT) AS CurrentTradeID, CAST(COALESCE(TRY_CAST(HH.HH_AFTER_QTY AS DECIMAL(6)), 0) AS DECIMAL(6, 0)) AS CurrentHolding, CAST(1 AS DECIMAL(5)) AS BatchID FROM Source.HoldingHistory AS HH, DimTrade AS DT WHERE HH.HH_T_ID = DT.TradeID;
